/* Zimmermann <zimm-*> render engine.
 *
 * No Shadow DOM, no customElements.define(). Each component file registers a
 * plain render function into window.ZIMM_RENDERERS; this file walks the page
 * once (on DOMContentLoaded), replaces every <zimm-*> tag's content with its
 * renderer's output, and sets display:contents on the wrapper so it disappears
 * from layout. One-time render, not reactive: attributes are read once, at
 * mount. This library exists to communicate design intent (see
 * _shared/authoring.md), not to ship as production components, so this trade
 * -off is intentional, not a limitation to work around.
 *
 * Load this file once per page, before any component's own script.
 * -------------------------------------------------------------------- */
(function () {
  'use strict';

  window.ZIMM_RENDERERS = window.ZIMM_RENDERERS || {};

  // ---- shared helpers, available to every component renderer ----
  window.ZIMM = {
    esc: function (s) {
      return (s == null ? '' : String(s)).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    },
    attr: function (el, name, def) {
      return el.hasAttribute(name) ? el.getAttribute(name) : (def == null ? '' : def);
    },
    bool: function (el, name) {
      return el.hasAttribute(name) && el.getAttribute(name) !== 'false';
    },
  };

  // ---- slot capture: bucket an element's original children by slot="..."
  // before its renderer replaces innerHTML. Only DIRECT children claim a
  // named slot; a nested [slot] belongs to an inner composed component. ----
  function captureSlots(el) {
    var slots = { default: '' };
    var tmp = document.createElement('div');
    while (el.firstChild) tmp.appendChild(el.firstChild);
    Array.prototype.slice.call(tmp.children).forEach(function (n) {
      if (n.hasAttribute('slot')) {
        var s = n.getAttribute('slot');
        n.removeAttribute('slot');
        slots[s] = (slots[s] || '') + n.outerHTML;
        tmp.removeChild(n);
      }
    });
    slots.default = tmp.innerHTML;
    return slots;
  }

  // ---- attributes that pass through from the wrapper tag onto whichever
  // rendered element carries data-ds-control (usually the real interactive
  // control: <button>, <input>, etc). A renderer does not need to read or
  // re-apply any of these itself. ----
  var PASS = ['id', 'onclick', 'onchange', 'oninput', 'disabled', 'value', 'name', 'aria-label', 'aria-hidden', 'tabindex'];

  function isZimm(el) {
    return el.tagName && el.tagName.toLowerCase().indexOf('zimm-') === 0 && !!window.ZIMM_RENDERERS[el.tagName.toLowerCase()];
  }

  function renderEl(el) {
    if (el._zimmRendered) return;
    el._zimmRendered = true;
    var slots = captureSlots(el); // raw children captured before any child renders
    el.innerHTML = window.ZIMM_RENDERERS[el.tagName.toLowerCase()](el, slots);
    var root = el.firstElementChild;
    var control = el.querySelector('[data-ds-control]') || root;
    if (control) {
      PASS.forEach(function (p) {
        if (el.hasAttribute(p)) { control.setAttribute(p, el.getAttribute(p)); el.removeAttribute(p); }
      });
      if (control.removeAttribute) control.removeAttribute('data-ds-control');
    }
    if (el.className && root) { root.className += ' ' + el.className; el.removeAttribute('class'); }
    if (el.getAttribute('style') && root) { root.setAttribute('style', (root.getAttribute('style') || '') + ';' + el.getAttribute('style')); el.removeAttribute('style'); }
    el.style.display = 'contents';
    descend(el); // render any nested <zimm-*> in the fresh subtree just inserted
  }

  function descend(el) {
    Array.prototype.slice.call(el.children).forEach(function (k) {
      if (isZimm(k)) renderEl(k); else descend(k);
    });
  }

  function run() {
    descend(document.body);
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', run);
  else run();
})();

