(function () {
  window.ZIMM_RENDERERS = window.ZIMM_RENDERERS || {};
  var esc = window.ZIMM.esc;
  var attr = window.ZIMM.attr;
  var bool = window.ZIMM.bool;

  var SCRIPT_URL = document.currentScript.src;
  var ICON_BASE = new URL('../icon/assets/', SCRIPT_URL).href;

  window.ZIMM_RENDERERS['zimm-button'] = function (el, slots) {
    var variant = attr(el, 'variant', 'primary');
    var inverseCls = bool(el, 'inverse') ? ' zimm-btn-inverse' : '';

    if (variant === 'icon') {
      var icon = attr(el, 'icon', '');
      var type = attr(el, 'type', 'button');
      var label = attr(el, 'label', icon);
      return '<button type="' + esc(type) + '" class="zimm-btn-icon' + inverseCls + '" aria-label="' + esc(label) + '" data-ds-control>'
        + '<img src="' + ICON_BASE + esc(icon) + '.svg" alt="" aria-hidden="true">'
        + '</button>';
    }

    var size = attr(el, 'size', 'large');
    var label = attr(el, 'label', 'Button');
    var cls = 'zimm-btn zimm-btn-' + variant + ' zimm-btn-' + size + inverseCls;
    if (bool(el, 'full-width')) cls += ' zimm-btn-full';

    return '<button type="' + esc(attr(el, 'type', 'button')) + '" class="' + cls + '" data-ds-control>' + esc(label) + '</button>';
  };
})();

