/* Design Tokens + Component Base Styles
   Source: MCP-Test--Don-t-Use (Zimmermann Design System 2026)
   Extracted: 2026-07-08
   Schema version: 1
   Token custom properties split into tokens/colors.css, tokens/typography.css,
   tokens/spacing.css: 2026-07-25. This file is the stable public entry point:
   every prototype, demo.html, and the catalog link to THIS file. Its public
   path and "loading it exposes every token" behaviour are unchanged; only its
   internal structure moved.
   Managed by /extract, do not edit manually.
   --------------------------------------------------------- */

@import url('./tokens/colors.css');
@import url('./tokens/typography.css');
@import url('./tokens/spacing.css');
@import url('./tokens/buttons.css');

:root {

  /* ---- Motion: PLACEHOLDER ----
     All transition and animation values below are provisional.
     Motion design is in progress and subject to change pending
     formal approval. Do not treat these values as final.
     --------------------------------------------------------- */

  /* ---- Motion: Durations ---- */
  --zimm-motion-duration-fast:    200ms;
  --zimm-motion-duration-default: 300ms;
  --zimm-motion-duration-slow:    500ms;

  /* ---- Motion: Easings ---- */
  --zimm-motion-easing-standard: ease;
  --zimm-motion-easing-slides:   cubic-bezier(0.87, 0, 0.13, 1);
  --zimm-motion-easing-fades:    cubic-bezier(0.37, 0, 0.63, 1);

}


body {
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

