(function () {
  window.ZIMM_RENDERERS = window.ZIMM_RENDERERS || {};
  var esc = window.ZIMM.esc;
  var attr = window.ZIMM.attr;
  var bool = window.ZIMM.bool;

  window.ZIMM_RENDERERS['zimm-input-action'] = function (el, slots) {
    var label       = attr(el, 'label', '');
    var type        = attr(el, 'type', 'text');
    var name        = attr(el, 'name', '');
    var placeholder = attr(el, 'placeholder', '');
    var icon        = attr(el, 'icon', 'chevron-right');
    var buttonType  = attr(el, 'button-type', 'submit');
    var buttonLabel = attr(el, 'button-label', 'Submit');
    var errorText   = attr(el, 'error-text', '');
    var inverse     = bool(el, 'inverse');

    // Molecule: composes zimm-text-input (with the icon button in its
    // "trailing" slot) and zimm-button variant="icon". Both are rendered
    // automatically by the runtime's page walk descending into this fresh
    // markup, as long as their own renderer scripts are also loaded (see
    // authoring.md "Internal composition"). class="zimm-input-action" on the
    // <zimm-text-input> tag rides the runtime's existing className
    // pass-through (renderEl: `root.className += ' ' + el.className`) onto
    // that component's own rendered root, the same way any external caller
    // adding a class to a <zimm-text-input> would.
    return '<zimm-text-input class="zimm-input-action"'
      + ' label="' + esc(label) + '"'
      + ' type="' + esc(type) + '"'
      + (name ? ' name="' + esc(name) + '"' : '')
      + (placeholder ? ' placeholder="' + esc(placeholder) + '"' : '')
      + (errorText ? ' error-text="' + esc(errorText) + '"' : '')
      + (inverse ? ' inverse' : '')
      + '>'
      + '<zimm-button slot="trailing" variant="icon"'
      + ' icon="' + esc(icon) + '"'
      + ' type="' + esc(buttonType) + '"'
      + ' label="' + esc(buttonLabel) + '"'
      + (inverse ? ' inverse' : '')
      + '></zimm-button>'
      + '</zimm-text-input>';
  };
})();

