1	/* Button component classes: .zimm-btn*
2	   Source: MCP-Test--Don-t-Use (Zimmermann Design System 2026)
3	   Component: zimm-button (02-design/library/elements/button/)
4	   Moved here from the component's own zimm-button.css: 2026-07-25.
5	   Promoted to a shared token-level file (imported by common.css, same as
6	   colors/typography/spacing) because zimm-btn* classes are reused directly
7	   by other components' native <button> markup (e.g. filters/sort controls),
8	   not only by zimm-button's own render function -- every page already links
9	   common.css, so this makes button styling available everywhere without a
10	   separate <link> per composing demo. The render function itself
11	   (zimm-button.js) still lives in its own element folder; only the CSS moved.
12	   Managed by /extract, do not edit manually.
13	   --------------------------------------------------------- */
14	
15	/* ---- Label variants (primary/secondary): shared structural rules ---- */
16	
17	.zimm-btn {
18	  position: relative;
19	  display: inline-flex;
20	  align-items: center;
21	  justify-content: center;
22	  gap: var(--zimm-size-action-gap);
23	  min-width: 80px;
24	  overflow: clip;
25	  cursor: pointer;
26	  font-family: var(--zimm-font-family-body);
27	  font-weight: var(--zimm-font-weight-medium);
28	  text-transform: uppercase;
29	  letter-spacing: var(--zimm-font-letterspacing-sm);
30	  transition: background-color 0.15s ease, color 0.15s ease, border-color 0.15s ease;
31	}
32	
33	.zimm-btn-full {
34	  display: flex;
35	  width: 100%;
36	}
37	
38	/* Size: Large | Medium in Figma. Both get an explicit, parallel rule here —
39	   neither is an implicit default baked into the base .zimm-btn rule, even
40	   though large happens to be the contract default. The renderer always emits
41	   a zimm-btn-[size] class (never omits it for the default), so the CSS
42	   should always have a matching rule for it to point to. */
43	
44	.zimm-btn-large {
45	  height: var(--zimm-size-action-height-lg);
46	  padding: 0 var(--zimm-size-action-padding-h-lg);
47	  font-size: var(--zimm-font-size-2xs);
48	  line-height: var(--zimm-font-lineheight-3xs);
49	}
50	
51	.zimm-btn-medium {
52	  height: var(--zimm-size-action-height-md);
53	  padding: 0 var(--zimm-size-action-padding-h-md);
54	  font-size: var(--zimm-font-size-3xs);
55	  line-height: var(--zimm-font-lineheight-2xs);
56	}
57	
58	/* ---- Resting colours ---- */
59	
60	.zimm-btn-primary {
61	  background: var(--zimm-color-action-primary-bg-default);
62	  color: var(--zimm-color-action-primary-text);
63	  border: none;
64	}
65	
66	.zimm-btn-primary.zimm-btn-inverse {
67	  background: var(--zimm-color-grey-white);
68	  color: var(--zimm-color-grey-900);
69	}
70	
71	.zimm-btn-secondary {
72	  background: transparent;
73	  color: var(--zimm-color-action-secondary-text);
74	  border: var(--zimm-border-width-default) solid var(--zimm-color-action-secondary-border);
75	}
76	
77	.zimm-btn-secondary.zimm-btn-inverse {
78	  color: var(--zimm-color-grey-white);
79	  border-color: var(--zimm-color-grey-white);
80	}
81	
82	/* ---- Hover ---- */
83	
84	.zimm-btn-primary:hover:not(:disabled) {
85	  background: var(--zimm-color-action-primary-bg-hover);
86	  color: var(--zimm-color-action-primary-text);
87	}
88	
89	.zimm-btn-primary.zimm-btn-inverse:hover:not(:disabled) {
90	  background: var(--zimm-color-ivory-100);
91	  color: var(--zimm-color-grey-900);
92	}
93	
94	.zimm-btn-secondary:hover:not(:disabled) {
95	  background: var(--zimm-color-action-secondary-bg-hover);
96	  color: var(--zimm-color-action-secondary-text);
