(function () {
  window.ZIMM_RENDERERS = window.ZIMM_RENDERERS || {};
  var esc = window.ZIMM.esc;
  var attr = window.ZIMM.attr;

  window.ZIMM_RENDERERS['zimm-product-detail-options'] = function (el, slots) {
    var productName   = attr(el, 'product-name', '');
    var price         = attr(el, 'price', '');
    var colourName    = attr(el, 'colour-name', '');
    var sizeOptions   = attr(el, 'size-options', '[]');
    var ctaLabel      = attr(el, 'cta-label', 'ADD TO BAG');
    var boutiqueHref  = attr(el, 'boutique-href', '#');
    var boutiqueLabel = attr(el, 'boutique-label', 'FIND IN BOUTIQUE');
    var styleCode     = attr(el, 'style-code', '');
    var modelInfo     = attr(el, 'model-info', '');

    var colourBlock = colourName
      ? '<p class="zimm-product-detail-options-colour-label">Colour: ' + esc(colourName) + '</p>'
        + '<div class="zimm-product-detail-options-swatches">' + (slots.swatches || '') + '</div>'
      : '';

    var metaBlock = '';
    if (modelInfo) metaBlock += '<p>' + esc(modelInfo) + '</p>';
    if (styleCode) metaBlock += '<p>Style Code: ' + esc(styleCode) + '</p>';

    return '<div class="zimm-product-detail-options">'

      + '<div class="zimm-product-detail-options-name-row">'
      + '<p class="zimm-product-detail-options-product-name">' + esc(productName) + '</p>'
      + '<zimm-add-to-wishlist></zimm-add-to-wishlist>'
      + '</div>'

      + '<p class="zimm-product-detail-options-price">' + esc(price) + '</p>'

      + '<div class="zimm-product-detail-options-description">' + (slots.description || '') + '</div>'

      + colourBlock

      + '<div class="zimm-product-detail-options-size-row">'
      + '<div class="zimm-product-detail-options-size-select">'
      + '<zimm-select placeholder="Size" options=\'' + sizeOptions + '\'></zimm-select>'
      + '</div>'
      + '<a class="zimm-product-detail-options-size-link" href="#">Find your size</a>'
      + '</div>'

      + '<div class="zimm-product-detail-options-cta-row">'
      + '<zimm-button variant="primary" size="large" label="' + esc(ctaLabel) + '" full-width></zimm-button>'
      + '</div>'

      + '<a class="zimm-product-detail-options-boutique-link" href="' + esc(boutiqueHref) + '">' + esc(boutiqueLabel) + '</a>'

      + '<div class="zimm-product-detail-options-accordions">' + (slots.accordions || '') + '</div>'

      + '<div class="zimm-product-detail-options-meta">' + metaBlock + '</div>'

      + '</div>';
  };
})();

