file.content:
/* ---- Base: shared structural rules (was :host + footer) ---- */

.zimm-footer,
.zimm-footer * {
  box-sizing: border-box;
}

.zimm-footer {
  display: block;
  background-color: var(--zimm-color-bg-05);
  width: 100%;
}

/* ---- Main grid: mobile default ---- */
.zimm-footer-main {
  display: grid;
  grid-template-columns: 1fr;
  grid-template-rows: auto auto auto;
  padding: var(--zimm-scale-4xl) var(--zimm-scale-800) 0;
}

.zimm-footer-subscribe { grid-column: 1; grid-row: 1; padding-bottom: var(--zimm-scale-600); }
.zimm-footer-links     { grid-column: 1; grid-row: 2; }
.zimm-footer-logo-area { grid-column: 1; grid-row: 3; padding: var(--zimm-scale-1000) 0; }

/* ---- Subscribe ---- */
.zimm-footer-label {
  margin: 0 0 var(--zimm-scale-600);
  font-family: var(--zimm-font-family-body);
  font-weight: var(--zimm-font-weight-medium);
  font-size: var(--zimm-font-size-3xs);
  line-height: normal;
  letter-spacing: var(--zimm-font-letterspacing-sm);
  text-transform: uppercase;
  color: var(--zimm-color-text-inverse-grey);
}

.zimm-footer-body-text {
  margin: 0 0 var(--zimm-scale-4xl);
  font-family: var(--zimm-font-family-body);
  font-weight: var(--zimm-font-weight-medium);
  font-size: var(--zimm-font-size-3xs);
  line-height: var(--zimm-font-lineheight-2xs);
  color: var(--zimm-color-text-inverse);
}

/* chevron-down is a dark-stroke SVG; invert to white on dark bg.
   Was `.locale zimm-icon` (element-tag selector reaching into the composed
   <zimm-icon>). <zimm-icon> is an inert display:contents shell after render
   (its wrapper tag has no box of its own), so a filter applied to the tag
   itself would silently no-op; retargeted to the icon's own rendered root
   class, same fix pattern used throughout this batch. */
.zimm-footer-locale .zimm-icon { filter: invert(1); }

/* ---- Links: mobile 2-col grid ---- */
.zimm-footer-links {
  display: grid;
  grid-template-columns: 1fr 1fr;
  column-gap: var(--zimm-scale-600);
  row-gap: var(--zimm-scale-600);
  padding: var(--zimm-scale-4xl) 0;
  border-top: 1px solid var(--zimm-color-grey-700);
  border-bottom: 1px solid var(--zimm-color-grey-700);
}

.zimm-footer-link-group:nth-child(1) { grid-column: 1; }
.zimm-footer-link-group:nth-child(2) { grid-column: 1; }
.zimm-footer-link-group:nth-child(3) { grid-column: 2; grid-row: 1 / span 2; }

.zimm-footer-group-label {
  margin: 0 0 var(--zimm-scale-600);
  font-family: var(--zimm-font-family-body);
  font-weight: var(--zimm-font-weight-medium);
  font-size: var(--zimm-font-size-3xs);
  line-height: normal;
  letter-spacing: var(--zimm-font-letterspacing-sm);
  text-transform: uppercase;
  color: var(--zimm-color-text-inverse-grey);
}

.zimm-footer-links ul {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: var(--zimm-scale-400);
}

.zimm-footer-links ul a {
  font-family: var(--zimm-font-family-body);
  font-weight: var(--zimm-font-weight-medium);
  font-size: var(--zimm-font-size-3xs);
  line-height: normal;
  letter-spacing: var(--zimm-font-letterspacing-sm);
  text-transform: uppercase;
  color: var(--zimm-color-text-inverse);
  text-decoration: none;
}

.zimm-footer-links ul a:hover { color: var(--zimm-color-text-inverse-grey); }

/* ---- Contact icon row ---- */
.zimm-footer-icon-row {
  display: flex;
  gap: var(--zimm-scale-400);
  align-items: center;
  padding-top: var(--zimm-scale-200);
}

.zimm-footer-icon-row a {
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

/* ---- Logo ---- */
.zimm-footer-logo-area { display: flex; }

/* ---- Bottom bar ---- */
.zimm-footer-bottom-bar {
  background-color: var(--zimm-color-bg-06);
  width: 100%;
}

.zimm-footer-bottom-bar-inner {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: var(--zimm-scale-2xl) var(--zimm-scale-800);
  flex-wrap: wrap;
  gap: var(--zimm-scale-300);
}

.zimm-footer-locale {
  display: inline-flex;
  align-items: center;
  gap: var(--zimm-scale-200);
  background: none;
  border: none;
  padding: 0;
  cursor: pointer;
  font-family: var(--zimm-font-family-body);
  font-weight: var(--zimm-font-weight-medium);
  font-size: var(--zimm-font-size-4xs);
  line-height: var(--zimm-font-lineheight-4xs);
  letter-spacing: var(--zimm-font-letterspacing-footer);
  text-transform: uppercase;
  color: var(--zimm-color-text-inverse);
  white-space: nowrap;
}

.zimm-footer-locale:focus-visible {
  outline: 2px solid var(--zimm-color-text-inverse);
  outline-offset: 2px;
}

.zimm-footer-legal {
  display: flex;
  align-items: center;
  gap: var(--zimm-scale-500);
  flex-wrap: wrap;
  justify-content: flex-end;
}

.zimm-footer-legal span,
.zimm-footer-legal a {
  font-family: var(--zimm-font-family-body);
  font-weight: var(--zimm-font-weight-medium);
  font-size: var(--zimm-font-size-4xs);
  line-height: var(--zimm-font-lineheight-4xs);
  letter-spacing: var(--zimm-font-letterspacing-footer);
  text-transform: uppercase;
  color: var(--zimm-color-text-inverse-grey);
  text-decoration: none;
  white-space: nowrap;
}

/* Mobile: hide legal links, keep copyright only */
.zimm-footer-legal-link { display: none; }

/* ---- Tablet: 768px+ ---- */
@media (min-width: 768px) {
  .zimm-footer-main {
    display: grid;
    grid-template-columns: 320px 1fr;
    grid-template-rows: auto auto;
    padding: var(--zimm-scale-1000) var(--zimm-scale-1000) 0;
    gap: 0 var(--zimm-scale-4xl);
  }

  .zimm-footer-subscribe {
    grid-column: 1;
    grid-row: 1;
    padding-bottom: var(--zimm-scale-1000);
  }

  .zimm-footer-logo-area {
    grid-column: 1;
    grid-row: 2;
    padding: 0 0 var(--zimm-scale-1000);
    align-items: flex-end;
  }

  .zimm-footer-links {
    grid-column: 2;
    grid-row: 1 / span 2;
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    column-gap: var(--zimm-scale-1000);
    align-items: start;
    border-top: none;
    border-bottom: none;
    padding: 0 0 var(--zimm-scale-1000);
  }

  .zimm-footer-link-group:nth-child(1),
  .zimm-footer-link-group:nth-child(2),
  .zimm-footer-link-group:nth-child(3) {
    grid-column: auto;
    grid-row: auto;
  }

  .zimm-footer-legal-link { display: inline; }

  .zimm-footer-bottom-bar-inner {
    padding: var(--zimm-scale-2xl) var(--zimm-scale-3xl);
  }
}

/* ---- Desktop: 1024px+ ---- */
@media (min-width: 1024px) {
  .zimm-footer-main {
    grid-template-columns: 320px 1fr 600px;
    grid-template-rows: auto auto;
    gap: 0 var(--zimm-scale-4xl);
    padding: var(--zimm-scale-4xl) var(--zimm-scale-3xl) 0;
  }

  .zimm-footer-logo-area {
    grid-column: 1;
    grid-row: 2;
    padding: var(--zimm-scale-5xl) 0 var(--zimm-scale-4xl);
    align-items: flex-end;
  }

  .zimm-footer-links {
    grid-column: 3;
    grid-row: 1 / span 2;
    grid-template-columns: repeat(3, 1fr);
    column-gap: var(--zimm-scale-1000);
  }

  .zimm-footer-link-group:nth-child(1),
  .zimm-footer-link-group:nth-child(2),
  .zimm-footer-link-group:nth-child(3) {
    grid-column: auto;
    grid-row: auto;
  }
}

