file.content:
/* ---- Host wrapper (was :host) ---- */

.zimm-product-detail-options {
  display: block;
  font-family: var(--zimm-font-family-body);
  color: var(--zimm-color-text-default);
}

/* ---- Name row: product name + wishlist toggle ---- */

.zimm-product-detail-options-name-row {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--zimm-scale-s);
  margin-bottom: var(--zimm-scale-xs);
}

.zimm-product-detail-options-product-name {
  margin: 0;
  font-family: var(--zimm-font-family-body);
  /* TODO: --zimm-font-size-base and --zimm-font-lineheight-tight are not
     defined in the current token set (02-design/library/tokens/typography.css).
     This gap predates this port (present unresolved in the original
     Shadow-DOM component); carried over unchanged per conversion instructions
     rather than guessed at. Flag as a token candidate for design to confirm. */
  font-size: var(--zimm-font-size-base);
  font-weight: var(--zimm-font-weight-medium);
  text-transform: uppercase;
  letter-spacing: var(--zimm-font-letterspacing-xs);
  line-height: var(--zimm-font-lineheight-tight);
}

.zimm-product-detail-options-price {
  margin: 0 0 var(--zimm-scale-m) 0;
  /* TODO: see --zimm-font-size-base note above. */
  font-size: var(--zimm-font-size-base);
  font-weight: var(--zimm-font-weight-regular);
}

/* ---- Description slot (was slot[name="description"]::slotted(*)) ---- */

.zimm-product-detail-options-description > * {
  font-family: var(--zimm-font-family-body);
  /* TODO: --zimm-font-size-sm and --zimm-font-lineheight-relaxed are not
     defined in the current token set; carried over unchanged, see note above. */
  font-size: var(--zimm-font-size-sm);
  line-height: var(--zimm-font-lineheight-relaxed);
  margin: 0;
}

.zimm-product-detail-options-description {
  /* TODO: see --zimm-font-size-sm / --zimm-font-lineheight-relaxed note above. */
  font-size: var(--zimm-font-size-sm);
  line-height: var(--zimm-font-lineheight-relaxed);
  margin-bottom: var(--zimm-scale-l);
}

/* ---- Colour + swatches ---- */

.zimm-product-detail-options-colour-label {
  margin: 0 0 var(--zimm-scale-s) 0;
  /* TODO: see --zimm-font-size-sm note above. */
  font-size: var(--zimm-font-size-sm);
}

.zimm-product-detail-options-swatches {
  display: flex;
  gap: var(--zimm-scale-xs);
  margin-bottom: var(--zimm-scale-l);
}

/* ---- Size row: size select + "Find your size" link ---- */

.zimm-product-detail-options-size-row {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: var(--zimm-scale-m);
  margin-bottom: var(--zimm-scale-l);
}

.zimm-product-detail-options-size-select { flex: 1; }

.zimm-product-detail-options-size-link {
  font-family: var(--zimm-font-family-body);
  /* TODO: see --zimm-font-size-sm note above. */
  font-size: var(--zimm-font-size-sm);
  color: var(--zimm-color-text-default);
  text-decoration: underline;
  text-underline-offset: 2px;
  white-space: nowrap;
  padding-bottom: 8px;
  transition: color var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard);
}
.zimm-product-detail-options-size-link:hover { color: var(--zimm-color-link-hover); }

/* ---- CTA ---- */

.zimm-product-detail-options-cta-row { margin-bottom: var(--zimm-scale-m); }

/* ---- Boutique link ---- */

.zimm-product-detail-options-boutique-link {
  display: block;
  font-family: var(--zimm-font-family-body);
  /* TODO: see --zimm-font-size-sm note above. */
  font-size: var(--zimm-font-size-sm);
  font-weight: var(--zimm-font-weight-medium);
  text-transform: uppercase;
  letter-spacing: var(--zimm-font-letterspacing-xs);
  color: var(--zimm-color-text-default);
  text-decoration: underline;
  text-underline-offset: 2px;
  margin-bottom: var(--zimm-scale-l);
  transition: color var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard);
}
.zimm-product-detail-options-boutique-link:hover { color: var(--zimm-color-link-hover); }

/* ---- Accordions ---- */

.zimm-product-detail-options-accordions {
  border-top: 1px solid var(--zimm-color-border-default);
  margin-bottom: var(--zimm-scale-l);
}

/* ---- Meta: model info / style code ---- */

.zimm-product-detail-options-meta {
  padding-top: var(--zimm-scale-m);
  border-top: 1px solid var(--zimm-color-border-default);
}

.zimm-product-detail-options-meta p {
  margin: 0 0 var(--zimm-scale-xs) 0;
  font-size: var(--zimm-font-size-xs);
  color: var(--zimm-color-text-muted);
  /* TODO: see --zimm-font-lineheight-relaxed note above. */
  line-height: var(--zimm-font-lineheight-relaxed);
}
.zimm-product-detail-options-meta p:last-child { margin-bottom: 0; }

